const { execution = {}, workflow = {} } = $input.first().json;
const message = String(execution.error?.message || 'Unknown error').slice(0, 900);
return [{
  json: {
    report: {
      workflow: String(workflow.name || 'unknown').slice(0, 120),
      executionId: String(execution.id || `noexec-${Date.now()}`),
      node: execution.lastNodeExecuted ? String(execution.lastNodeExecuted).slice(0, 120) : undefined,
      message,
    },
    executionUrl: execution.url || '',
  },
}];

const crypto = require('crypto');
const base = String($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
const path = '/n8n/automation-error';
return $input.all().map((item, index) => {
  const body = JSON.stringify(item.json.report);
  const t = Math.floor(Date.now() / 1000);
  const v1 = crypto.createHmac('sha256', $env.N8N_CONVEX_SECRET).update(`${t}.POST.${path}.${body}`).digest('hex');
  return { json: { url: base + path, body, signature: `t=${t},v1=${v1}` }, pairedItem: { item: index } };
});

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const { report, executionUrl } = $('Build report').first().json;
const lines = [
  `Workflow: ${report.workflow}`,
  `Step: ${report.node || 'unknown'}`,
  `Execution: ${report.executionId}`,
  `Error: ${report.message}`,
];
return [{
  json: {
    idempotencyKey: `alert:${report.executionId}`,
    email: {
      from: $env.RESEND_FROM,
      to: [$env.ADMIN_ALERT_EMAIL],
      subject: `[LendLoop] ${report.workflow} failed at ${report.node || 'unknown step'}`,
      text: lines.join('\n') + (executionUrl ? `\n\nOpen in n8n: ${executionUrl}` : ''),
      html: `<pre style="font:14px/1.5 ui-monospace,Menlo,monospace;white-space:pre-wrap">${esc(lines.join('\n'))}</pre>` +
        (executionUrl ? `<p><a href="${esc(executionUrl)}">Open the execution in n8n</a></p>` : ''),
    },
  },
}];
